record R(p: path)
record Seed(n: number)
module Pick(p: path, q: path, which: number) {
 const A: Seed = Seed(n: 3)
 const B: Seed = Seed(n: 5)
 const Values: Seed[] = [A, B]
 const Mapped: R[] = for item in Values { R(p: segment(start: (0, 0), end: (item.n, 0))) }
 const Chosen: R = Mapped[which]
 export const out: path = Chosen.p
}
const P: path = segment(start: (0, 0), end: (3, 4))
const Q: path = segment(start: (0, 0), end: (5, 12))
instance One = Pick(p: P, q: Q, which: 1)
const First: path = One::out
const L: number = First.length

