record R(p: path)
module Pick(p: path, q: path, present: boolean) {
 const A: R = R(p: p)
 const B: R = R(p: q)
 const Values: R[] = [A]
 const Fallback: R[] = [B]
 const Maybe: R[]? = if (present) { Values }
 const Source: R[] = match Maybe { none => Fallback some held => held }
 const Mapped: R[] = for item in Source { R(p: item.p) }
 const Chosen: R = Mapped[0]
 export const out: path = Chosen.p
}
const P: path = segment(start: (0, 0), end: (3, 4))
const Q: path = segment(start: (0, 0), end: (5, 12))
instance One = Pick(p: P, q: Q, present: true)
const First: path = One::out
const L: number = First.length

