module Make(n: number, present: boolean) {
 const Values: number[] = [n]
 const Fallback: number[] = [n + 100]
 const Maybe: number[]? = if (present) { Values }
 const Source: number[] = match Maybe { none => Fallback some held => held }
 const Alias: number[] = Source
 export const out: path = segment(start: (0, 0), end: (Alias[0], 0))
}
instance One = Make(n: 19, present: true)
instance Two = Make(n: 43, present: false)
const First: path = One::out
const Second: path = Two::out
const L: number = First.length
const M: number = Second.length

